function (triggerType, triggerData, reactorToken, item, activationName, api) {
const weapon = triggerData.weapon;
if (!weapon) return false;

const size = String(weapon.system?.size ?? "").toLowerCase();
const isHeavy = size === "heavy" || size === "superheavy";
const isMelee = /\bmelee\b/i.test(api.getWeaponType(weapon));
const critTargets = (triggerData.targets ?? [])
  .filter(entry => entry.crit)
  .map(entry => entry.target);

if (!critTargets.length) return false;
return isHeavy && isMelee && api.checkGate(reactorToken, "primrose_mag_weight"); }

