async function (triggerType, triggerData, reactorToken, item, activationName, api) {


    const choiceb = await api.askCard({
  title: "Magnetic Weight Redistribution",
  description: "Attempt to force a hull save?",
  yesText: "Use",
  noText: "Skip",
  owner: reactorToken,
  originToken: reactorToken,
  item
});
    if (!choiceb.confirmed) return;


const critTargets = (triggerData.targets ?? [])
  .filter(entry => entry.crit)
  .map(entry => entry.target);

if (!critTargets.length) return;


const chosen = await api.chooseToken(reactorToken, {
  selection: critTargets,
  count: 1,
  title: "Choose a Critical Hit Target",
  description: "Select one target you critically hit.",
  soft: false
});

if (!await api.consumeOncePerRound(
      reactorToken,
      "primrose_mag_weight"
    )) return;


const target = chosen?.[0];
if (!target) return; // Selection cancelled.
    const result = await api.executeForceCheck("HULL", [target], {saveVs: reactorToken})
    if (result.results[0].passed) return;




        await api.applyEffectsToTokens({
    tokens: [target],
    effectNames: "lancer.statusIconsNames.prone",
    duration: {
        label: "indefinite",
        turns: null,
        rounds: null }});

}

async function (triggerType, triggerData, reactorToken, item, activationName, api) {
  const actor = reactorToken.actor;
  const bonusId = `primrose_${actor.id}`;

  const bonus = api.getConstantBonuses(actor)
    .find(b => b.id === bonusId);

  const hasShield = !!api.findEffectOnToken(
    reactorToken,
    "Shimmering Shield"
  );

  const maxBonus = hasShield ? 5 : 3;
  const preValue = Number(bonus?.val ?? 0);

  let value = preValue;

  if (preValue < maxBonus) {
    value = preValue + 1;
  } else if (hasShield) {
    const roll = await new Roll("1d3").evaluate();
    const overshield = Number(actor.system.overshield.value ?? 0);

    await actor.update({
      "system.overshield.value": overshield + roll.total
    });
  }

  if (bonus) {
    await api.removeConstantBonus(actor, bonusId);
  }

  await api.addConstantBonus(actor, {
    id: bonusId,
    name: "Effervescent Immunity",
    type: "stat",
    stat: "system.evasion",
    val: value,
    statMode: "add"
  });
}

